def separate_paren_groups(paren_string: str) -> List[str]:
    if not isinstance(paren_string, str):
        raise ValueError("Input must be a string.")

    paren_string = paren_string.replace(" ", "")

    def is_balanced(group: str) -> bool:
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    result = []
    current_group = ""

    for char in paren_string:
        if char == '(':
            current_group += char
        elif char == ')':
            current_group += char
            if is_balanced(current_group):
                result.append(current_group)
                current_group = ""

    if current_group:
        if is_balanced(current_group):
            result.append(current_group)

    return result

