from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def parse_group(group: str) -> int:
        level = 0
        max_level = 0
        for char in group:
            if char == '(':
                level += 1
                max_level = max(max_level, level)
            elif char == ')':
                level -= 1
        return max_level

    if not isinstance(paren_string, str) or not all(isinstance(g, str) for g in paren_string.split()):
        raise TypeError("Input must be a string with groups of parentheses separated by spaces.")

    groups = paren_string.split()
    valid_groups = [g for g in groups if g]
    if not valid_groups:
        return []

    return [parse_group(g) for g in valid_groups]

