def greatest_common_divisor(a: int, b: int) -> int:
    def gcd_loop(a, b):
        while b:
            a, b = b, a % b
        return abs(a)

    if a == 0 and b == 0:
        return 0
    if a == 0 or b == 0:
        return max(abs(a), abs(b))
    return gcd_loop(abs(a), abs(b))

