        raise ValueError("p cannot be 1 as division by zero is undefined.")
    if n == 0:
        return 1 % p
    n %= p - 1  # Convert negative n to positive equivalent
    if n == 0:
        return 1  # 2^0 % p is always 1
    if n == p - 1:
        return 2 % p  # Special case for 2^(p-1) % p = 1
    result = 1
    for _ in range(n):
        result = (result * 2) % p
    return result

