def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    if not all(isinstance(item, str) and all(c in ('(', ')') for c in item) for item in lst):
        return 'No'

    total_open = total_close = 0
    for item in lst:
        total_open += item.count('(')
        total_close += item.count(')')

    if total_open != total_close:
        return 'No'

    for i in range(2):
        s = lst[i] + ''.join(lst[(i+1)%2])
        if is_balanced(s):
            return 'Yes'

    return 'No'

