def minPath(grid, k):
    N = len(grid)
    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def dfs(x, y, path, visited, k):
        if k == 0:
            nonlocal min_path, min_values
            if len(path) < len(min_path):
                min_path = path[:]
                min_values = [grid[i][j] for i, j in path]
            return
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                dfs(nx, ny, path + [(nx, ny)], visited, k - 1)
                visited.remove((nx, ny))

    min_path, min_values = [], []
    for i in range(N):
        for j in range(N):
            visited = set([(i, j)])
            dfs(i, j, [(i, j)], visited, k - 1)
    return min_values

